package cmds

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/fatih/color"
	"github.com/scottjr632/dotctl/internal/config"
	"github.com/scottjr632/dotctl/internal/git"
	"github.com/spf13/cobra"
)

var (
	checkoutBackupExisting bool
	checkoutBackupDir      string
)

type checkoutResult struct {
	BackupDir string   `json:"backup_dir,omitempty"`
	BackedUp  []string `json:"backed_up"`
}

var checkoutCmd = &cobra.Command{
	Use:   "checkout",
	Short: "Check out tracked dotfiles into the work tree",
	Long:  "Check out tracked dotfiles into the work tree, optionally backing up paths that would block a first checkout",
	Args:  cobra.NoArgs,
	RunE: func(cmd *cobra.Command, args []string) error {
		if checkoutBackupDir != "" && !checkoutBackupExisting {
			return &cliError{code: "INVALID_ARGUMENT", err: errors.New("--backup-dir requires --backup-existing")}
		}

		cfg, err := commandConfig()
		if err != nil {
			return err
		}
		if !checkoutBackupExisting {
			if dryRun {
				return writePlan(cmd, checkoutAction(cfg))
			}
			if err := git.GitCmd(cfg, "checkout").ExecuteInTerminal(); err != nil {
				return fmt.Errorf("checkout failed; resolve conflicting files before retrying: %w", err)
			}
			return nil
		}

		indexed, err := git.ListTrackedFiles(cfg).Unwrap()
		if err != nil {
			return err
		}
		if len(indexed) != 0 {
			return &cliError{
				code: "INVALID_ARGUMENT",
				err:  errors.New("--backup-existing is only available before the first checkout"),
			}
		}
		tracked, err := git.ListHeadFiles(cfg).Unwrap()
		if err != nil {
			return err
		}
		collisions, err := existingCheckoutPaths(git.WorkTree(), tracked)
		if err != nil {
			return err
		}

		if dryRun {
			actions := []planAction{}
			if len(collisions) != 0 {
				location := checkoutBackupDir
				if location == "" {
					location = filepath.Join(config.DirPath(), "backups", "<timestamp>")
				}
				actions = append(actions, action("backup_existing", fmt.Sprintf("Move %d existing path(s) to %s", len(collisions), location)))
			}
			return writePlan(cmd, append(actions, checkoutAction(cfg))...)
		}

		result := checkoutResult{BackedUp: collisions}
		if len(collisions) != 0 {
			result.BackupDir = checkoutBackupDir
			if result.BackupDir == "" {
				result.BackupDir = filepath.Join(config.DirPath(), "backups", time.Now().UTC().Format("20060102T150405.000000000Z"))
			}
			if err := backupCheckoutPaths(git.WorkTree(), result.BackupDir, collisions); err != nil {
				return fmt.Errorf("back up existing paths: %w", err)
			}
		}

		if err := git.GitCmd(cfg, "checkout").ExecuteInTerminal(); err != nil {
			if result.BackupDir != "" {
				return fmt.Errorf("checkout failed after existing paths were backed up to %s: %w", result.BackupDir, err)
			}
			return fmt.Errorf("checkout failed: %w", err)
		}
		if jsonOutput {
			return writeJSON(cmd, result)
		}
		if result.BackupDir != "" {
			color.New(color.FgGreen).Fprintf(cmd.OutOrStdout(), "Backed up %d existing path(s) to %s\n", len(result.BackedUp), result.BackupDir)
		}
		color.New(color.FgGreen).Fprintln(cmd.OutOrStdout(), "Successfully checked out dotfiles")
		return nil
	},
}

func checkoutAction(cfg config.Config) planAction {
	return action("checkout", fmt.Sprintf("Check out tracked files from %s into %s", cfg.DotfilesGitPath, git.WorkTree()))
}

func existingCheckoutPaths(workTree string, tracked []string) ([]string, error) {
	tracked = append([]string(nil), tracked...)
	sort.Strings(tracked)
	selected := map[string]bool{}
	paths := []string{}

	for _, trackedPath := range tracked {
		rel := filepath.Clean(filepath.FromSlash(trackedPath))
		if rel == "." || filepath.IsAbs(rel) || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			return nil, fmt.Errorf("invalid tracked path %q", trackedPath)
		}

		parts := strings.Split(rel, string(filepath.Separator))
		for index := range parts {
			candidate := filepath.Join(parts[:index+1]...)
			if hasSelectedAncestor(selected, candidate) {
				break
			}
			info, err := os.Lstat(filepath.Join(workTree, candidate))
			if errors.Is(err, os.ErrNotExist) {
				break
			}
			if err != nil {
				return nil, err
			}
			isTrackedPath := index == len(parts)-1
			if !isTrackedPath && info.IsDir() {
				continue
			}
			selected[candidate] = true
			paths = append(paths, filepath.ToSlash(candidate))
			break
		}
	}
	return paths, nil
}

func hasSelectedAncestor(selected map[string]bool, path string) bool {
	for candidate := path; candidate != "."; candidate = filepath.Dir(candidate) {
		if selected[candidate] {
			return true
		}
	}
	return false
}

func backupCheckoutPaths(workTree, backupDir string, paths []string) error {
	backupDir, err := filepath.Abs(backupDir)
	if err != nil {
		return err
	}
	if _, err := os.Lstat(backupDir); err == nil {
		return fmt.Errorf("backup directory already exists: %s", backupDir)
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}

	for _, path := range paths {
		source := filepath.Join(workTree, filepath.FromSlash(path))
		if containsPath(source, backupDir) {
			return fmt.Errorf("backup directory %s is inside path being backed up: %s", backupDir, path)
		}
	}
	if err := os.MkdirAll(backupDir, 0o700); err != nil {
		return err
	}

	moved := []string{}
	for _, path := range paths {
		rel := filepath.FromSlash(path)
		source := filepath.Join(workTree, rel)
		destination := filepath.Join(backupDir, rel)
		if err := os.MkdirAll(filepath.Dir(destination), 0o755); err != nil {
			return rollbackCheckoutBackup(workTree, backupDir, moved, err)
		}
		if err := os.Rename(source, destination); err != nil {
			return rollbackCheckoutBackup(workTree, backupDir, moved, err)
		}
		moved = append(moved, path)
	}
	return nil
}

func rollbackCheckoutBackup(workTree, backupDir string, moved []string, originalErr error) error {
	for index := len(moved) - 1; index >= 0; index-- {
		rel := filepath.FromSlash(moved[index])
		source := filepath.Join(backupDir, rel)
		destination := filepath.Join(workTree, rel)
		if err := os.MkdirAll(filepath.Dir(destination), 0o755); err != nil {
			return fmt.Errorf("%w; also failed to restore %s: %v", originalErr, moved[index], err)
		}
		if err := os.Rename(source, destination); err != nil {
			return fmt.Errorf("%w; also failed to restore %s: %v", originalErr, moved[index], err)
		}
	}
	_ = os.RemoveAll(backupDir)
	return originalErr
}

func containsPath(parent, child string) bool {
	rel, err := filepath.Rel(parent, child)
	return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

func init() {
	checkoutCmd.Flags().BoolVar(&checkoutBackupExisting, "backup-existing", false, "back up paths that would block the first checkout")
	checkoutCmd.Flags().StringVar(&checkoutBackupDir, "backup-dir", "", "backup destination (default: CONFIG_DIR/backups/TIMESTAMP)")
	rootCmd.AddCommand(checkoutCmd)
}
package cmds

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"

	"github.com/scottjr632/dotctl/internal/config"
	"github.com/scottjr632/dotctl/internal/terminalcmd"
	"github.com/spf13/cobra"
)

type response struct {
	OK    bool           `json:"ok"`
	Kind  string         `json:"kind"`
	Data  any            `json:"data,omitempty"`
	Error *errorResponse `json:"error,omitempty"`
}

type errorResponse struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

type planAction struct {
	Operation   string `json:"operation"`
	Description string `json:"description"`
}

type planData struct {
	Actions []planAction `json:"actions"`
}

type commandResult struct {
	Command string `json:"command"`
	Output  string `json:"output,omitempty"`
}

type cliError struct {
	code string
	data any
	err  error
}

func (e *cliError) Error() string {
	return e.err.Error()
}

func (e *cliError) Unwrap() error {
	return e.err
}

var responseWritten bool

func wantsJSON(_ *cobra.Command) bool {
	return jsonOutput
}

func action(operation, description string) planAction {
	return planAction{Operation: operation, Description: description}
}

func writeJSON(cmd *cobra.Command, data any) error {
	return writeResponse(cmd.OutOrStdout(), response{OK: true, Kind: "result", Data: data})
}

func writePlan(cmd *cobra.Command, actions ...planAction) error {
	if jsonOutput {
		return writeResponse(cmd.OutOrStdout(), response{OK: true, Kind: "plan", Data: planData{Actions: actions}})
	}

	fmt.Fprintln(cmd.OutOrStdout(), "Dry run; no changes made:")
	for _, action := range actions {
		fmt.Fprintln(cmd.OutOrStdout(), "- "+action.Description)
	}
	return nil
}

func writeCommandResult(writer io.Writer, command, output string) error {
	return writeResponse(writer, response{
		OK:   true,
		Kind: "result",
		Data: commandResult{Command: command, Output: strings.TrimSpace(output)},
	})
}

func writeErrorResponse(writer io.Writer, err error) error {
	payload := response{
		OK:   false,
		Kind: "error",
		Error: &errorResponse{
			Code:    errorCode(err),
			Message: err.Error(),
		},
	}
	var cliErr *cliError
	if errors.As(err, &cliErr) {
		payload.Data = cliErr.data
	} else if output := strings.TrimSpace(terminalcmd.CapturedOutput()); output != "" {
		payload.Data = commandResult{Command: executedCommand, Output: output}
	}
	return writeResponse(writer, payload)
}

func writeResponse(writer io.Writer, payload response) error {
	responseWritten = true
	return json.NewEncoder(writer).Encode(payload)
}

func errorCode(err error) string {
	var cliErr *cliError
	if errors.As(err, &cliErr) {
		return cliErr.code
	}
	if errors.Is(err, config.ErrConfigMissing) {
		return "CONFIG_NOT_FOUND"
	}
	if errors.Is(err, config.ErrConfigInvalid) {
		return "CONFIG_INVALID"
	}
	if errors.Is(err, os.ErrPermission) {
		return "PERMISSION_DENIED"
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		return "EXTERNAL_COMMAND_FAILED"
	}
	message := strings.ToLower(err.Error())
	if strings.Contains(message, "required") || strings.Contains(message, "unknown flag") || strings.Contains(message, "accepts ") {
		return "INVALID_ARGUMENT"
	}
	return "COMMAND_FAILED"
}
package cmds

import (
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/scottjr632/dotctl/internal/config"
	"github.com/scottjr632/dotctl/internal/git"
	"github.com/scottjr632/dotctl/internal/terminalcmd"
	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

var (
	configDir       string
	workTree        string
	nonInteractive  bool
	assumeYes       bool
	dryRun          bool
	jsonOutput      bool
	executedCommand = "dotctl"
)

var rootCmd = &cobra.Command{
	Use:           "dotctl",
	Short:         "Manage dotfiles stored in a bare Git repository",
	Long:          "Manage dotfiles stored in a bare Git repository",
	SilenceErrors: true,
	SilenceUsage:  true,
	PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
		if jsonOutput && (cmd.Name() == "completion" || cmd.Parent() != nil && cmd.Parent().Name() == "completion") {
			return &cliError{code: "JSON_UNSUPPORTED", err: fmt.Errorf("JSON output is not supported for shell completion generation")}
		}
		if configDir != "" {
			config.SetDir(configDir)
		}
		if workTree != "" {
			git.SetWorkTree(workTree)
		}
		if jsonOutput {
			nonInteractive = true
		}
		git.SetNonInteractive(nonInteractive)
		terminalcmd.SetCaptureOutput(jsonOutput)
		executedCommand = cmd.CommandPath()
		return nil
	},
}

func init() {
	rootCmd.PersistentFlags().StringVar(&configDir, "config-dir", "", "directory containing the dotctl config (or DOTCTL_CONFIG_DIR)")
	rootCmd.PersistentFlags().StringVar(&workTree, "work-tree", "", "Git work tree to manage (or DOTCTL_WORK_TREE)")
	rootCmd.PersistentFlags().BoolVar(&nonInteractive, "non-interactive", false, "fail instead of prompting or opening an editor")
	rootCmd.PersistentFlags().BoolVarP(&assumeYes, "yes", "y", false, "confirm requested operations")
	rootCmd.PersistentFlags().BoolVar(&dryRun, "dry-run", false, "describe changes without applying them")
	rootCmd.PersistentFlags().BoolVar(&jsonOutput, "json", false, "output one machine-readable JSON document")

	defaultHelp := rootCmd.HelpFunc()
	rootCmd.SetHelpFunc(func(cmd *cobra.Command, args []string) {
		if !jsonOutput {
			defaultHelp(cmd, args)
			return
		}
		_ = writeJSON(cmd, commandHelp(cmd))
	})
}

type helpCommand struct {
	Name        string `json:"name"`
	Description string `json:"description"`
}

type helpFlag struct {
	Name        string `json:"name"`
	Shorthand   string `json:"shorthand,omitempty"`
	Description string `json:"description"`
}

type helpData struct {
	Command     string        `json:"command"`
	Usage       string        `json:"usage"`
	Description string        `json:"description"`
	Commands    []helpCommand `json:"commands"`
	Flags       []helpFlag    `json:"flags"`
}

func commandHelp(cmd *cobra.Command) helpData {
	commands := make([]helpCommand, 0, len(cmd.Commands()))
	for _, child := range cmd.Commands() {
		if child.IsAvailableCommand() {
			commands = append(commands, helpCommand{Name: child.Name(), Description: child.Short})
		}
	}
	flags := []helpFlag{}
	cmd.Flags().VisitAll(func(flag *pflag.Flag) {
		flags = append(flags, helpFlag{Name: flag.Name, Shorthand: flag.Shorthand, Description: flag.Usage})
	})
	description := cmd.Long
	if description == "" {
		description = cmd.Short
	}
	return helpData{
		Command:     cmd.CommandPath(),
		Usage:       cmd.UseLine(),
		Description: description,
		Commands:    commands,
		Flags:       flags,
	}
}

func inspectionConfig() (config.Config, error) {
	return config.Preview().Unwrap()
}

func commandConfig() (config.Config, error) {
	if dryRun {
		return inspectionConfig()
	}
	return config.Get().Unwrap()
}

func Execute() error {
	return execute(os.Args[1:], os.Stdout, os.Stderr)
}

func execute(args []string, stdout, stderr io.Writer) error {
	responseWritten = false
	executedCommand = "dotctl"
	terminalcmd.ResetCapturedOutput()
	terminalcmd.SetCaptureOutput(false)

	preparedArgs, err := prepareGitArgs(args)
	if err != nil {
		if jsonOutput {
			_ = writeErrorResponse(stdout, err)
		} else {
			fmt.Fprintln(stderr, "dotctl:", err)
		}
		return err
	}
	rootCmd.SetArgs(preparedArgs)
	rootCmd.SetOut(stdout)
	rootCmd.SetErr(stderr)

	err = rootCmd.Execute()
	if jsonOutput {
		if err != nil && !responseWritten {
			_ = writeErrorResponse(stdout, err)
		}
		if err == nil && !responseWritten {
			return writeCommandResult(stdout, executedCommand, terminalcmd.CapturedOutput())
		}
		return err
	}
	if err != nil {
		fmt.Fprintln(stderr, "dotctl:", err)
	}
	return err
}

// Cobra's DisableFlagParsing is required to pass arbitrary flags to Git, but it
// also skips parent flag parsing. Parse only the global flags before "git" and
// leave everything after it untouched for Git.
func prepareGitArgs(args []string) ([]string, error) {
	gitIndex := gitCommandIndex(args)
	if gitIndex <= 0 {
		return args, nil
	}
	if err := rootCmd.PersistentFlags().Parse(args[:gitIndex]); err != nil {
		return nil, err
	}
	return append([]string{"git"}, args[gitIndex+1:]...), nil
}

func gitCommandIndex(args []string) int {
	for index := 0; index < len(args); index++ {
		switch args[index] {
		case "git":
			return index
		case "--config-dir", "--work-tree":
			index++
		case "--json", "--dry-run", "--non-interactive", "--yes", "-y":
			continue
		default:
			if strings.HasPrefix(args[index], "--config-dir=") ||
				strings.HasPrefix(args[index], "--work-tree=") ||
				strings.HasPrefix(args[index], "--json=") ||
				strings.HasPrefix(args[index], "--dry-run=") ||
				strings.HasPrefix(args[index], "--non-interactive=") ||
				strings.HasPrefix(args[index], "--yes=") {
				continue
			}
			return -1
		}
	}
	return -1
}

