type NonEmptyDirError struct {
	error
}

func IsNonEmptyDirError(err error) bool {
	if err == nil {
		return false
	}
	_, ok := err.(NonEmptyDirError)
	return ok
}

var (
	workTreeOverride string
	nonInteractive   bool
)

type InitRepoOptions struct {
	Path string
