		return result.Err[StatusInfo](fmt.Errorf("unexpected upstream counts: %q", strings.TrimSpace(counts)))
	}
	behind, behindErr := strconv.Atoi(fields[0])
	ahead, aheadErr := strconv.Atoi(fields[1])
	if behindErr != nil || aheadErr != nil {
		return result.Err[StatusInfo](fmt.Errorf("unexpected upstream counts: %q", strings.TrimSpace(counts)))
